// `pub use`, not `use`: the generated `frb_generated.rs` refers to every
// bridged type as `crate::api::<Name>`, so each one has to be nameable through
// this module. (Re-exporting them is harmless — this crate is a cdylib; it has
// no Rust downstream.)
pub use crate::{KeypairDto, WorkspaceKeyLabel};
