pub use comrade_ui::{
    BridgeEvent, CallRecordDto, CallSessionDto, CallSignalDto, ChitthiDto, ComradeDto, ContactDto,
    ConversationDto, CrisisResourceDto, DirectMessageDto, FoundProfileDto, IceServerDto,
    IdentityDto, JournalEntryDto, MediaBytesDto, MediaMessageDto, MeshStatusDto, MessageDto,
    MessageRequestDto, MetricDto, PresenceDto, ProfileDto, TaraMessageDto, TurnServerStatusDto,
    UiError, UpiIntentDto, WorkspaceDto,
};

/// The process-global runtime every function in this module reads.
///
/// `pub(crate)` rather than private so `crate`'s tests can assert — with
/// `Arc::ptr_eq` — that this ABI and the uniffi one really are looking at one
/// object. Never exported to Dart (`ComradeRuntime` is not an FRB type).
pub(crate) fn runtime() -> &'static Arc<RwLock<ComradeRuntime>> {
    crate::global_runtime()
}

/// Runs once, when the Dart side first loads the library.
///
/// `setup_default_user_utils` routes the `log` crate to logcat/oslog and
/// installs a panic hook that logs the backtrace. The hook only *observes* —
/// it does not stop unwinding — so uniffi's `catch_unwind` at the Kotlin
/// boundary still turns a panic into a `PanicException` rather than a crash.
/// This crate itself logs through `tracing`, not `log`; the bridge is for
/// flutter_rust_bridge's own diagnostics.
#[frb(init)]
pub fn init_app() {
    flutter_rust_bridge::setup_default_user_utils();
}

