/// `signal` crosses as the real [`CallSignal`] enum, not a JSON blob — only
/// this crate still round-trips it through JSON internally, since that's the
/// wire format the encrypted DM channel carries.
///
/// See [`broadcast_chitthi`] for the lock discipline.
pub async fn send_call_signal(
    peer: String,
    call_id: String,
    media: CallMediaKind,
    signal: CallSignal,
) -> Result<(), UiError> {
    let signal_json = serde_json::to_string(&signal).map_err(|e| UiError::Engine(e.to_string()))?;
    let handles = runtime().read().await.handles();
    handles
        .send_call_signal(&peer, &call_id, media.as_str(), &signal_json)
        .await
}

