// ── Push events ──────────────────────────────────────────────────────────────

/// Every [`BridgeEvent`], as a Dart `Stream`.
///
/// The Dart counterpart of `Comrade::set_event_listener`, and deliberately
/// sourced from the *same* two `tokio::sync::broadcast` channels the uniffi
/// listener forwards — `broadcast` fans out to every receiver, so a Kotlin
/// service listening through uniffi and a Flutter UI listening through this
/// stream both see every event, simultaneously, with neither starving the
/// other.
///
/// Two channels are merged, exactly as `set_event_listener` forwards two:
/// the critical stream (DMs, requests, call signals, mesh/ledger updates) and
/// the separate, small, deliberately-lossy `IncomingChitthi` feed stream (see
/// `comrade_ui::ComradeRuntime::subscribe_feed_events`, AUDIT.md COMMS-04), so
/// a public-feed flood can never delay a call signal queued behind it.
///
/// Subscribing late is safe but not retroactive: `broadcast` receivers only
/// see events sent after they subscribe, so call this before [`unlock_vault`].
/// Dropping the Dart subscription ends the task.
pub async fn bridge_event_stream(sink: StreamSink<BridgeEvent>) {
    let (critical_rx, feed_rx) = {
        let guard = runtime().read().await;
        (guard.subscribe_events(), guard.subscribe_feed_events())
    };
    // `sink.add` returns `Err` once Dart has dropped the subscription.
    pump_bridge_events(critical_rx, feed_rx, |event| sink.add(event).is_ok()).await
}

/// The fan-in half of [`bridge_event_stream`], with the Dart sink replaced by
/// `emit` (returning `false` when the consumer is gone).
///
/// Split out purely so it can be tested: a real `StreamSink` needs a live Dart
/// isolate port to construct, which no Rust test can provide. `pub(crate)`, so
/// FRB's parser leaves it alone — only `pub` items in this module become Dart
/// functions.
pub(crate) async fn pump_bridge_events<F>(
    mut critical_rx: tokio::sync::broadcast::Receiver<BridgeEvent>,
    mut feed_rx: tokio::sync::broadcast::Receiver<BridgeEvent>,
    mut emit: F,
) where
    F: FnMut(BridgeEvent) -> bool,
{
    // `broadcast::Receiver::recv` is cancel-safe, so `select!` dropping the
    // loser's future each iteration cannot lose an event on that channel.
    //
    // `Lagged` means this receiver fell behind *that channel's own* ring
    // buffer — never a cross-channel effect, since the two have independent
    // buffers. Log the skip count and keep going rather than tear the stream
    // down; `Closed` only happens when the runtime itself is going away.
    loop {
        let event = tokio::select! {
            r = critical_rx.recv() => r,
            r = feed_rx.recv() => r,
        };
        match event {
            Ok(event) => {
                if !emit(event) {
                    break;
                }
            }
            Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped)) => {
                tracing::warn!(
                    skipped,
                    "Dart event stream fell behind a broadcast channel's capacity; \
                     some events were skipped"
                );
            }
            Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
        }
    }
}
